script:
frappe.ui.form.on("Payment Request", {
	refresh(frm) {
		if (frm.is_new() || frm.doc.docstatus !== 0) {
			return;
		}

		frm.add_custom_button(
			__("Copy approval link"),
			() => {
				const path = `/app/payment-request/${encodeURIComponent(frm.doc.name)}`;
				const url = `${window.location.origin}${path}`;
				frappe.utils.copy_to_clipboard(url);
				frappe.show_alert({
					message: __(
						"Link copied. Send to the next approver via IM (login and approver role required)."
					),
					indicator: "green",
				});
			},
			__("Share")
		);

		frappe.xcall("frappe.model.workflow.get_transitions", { doc: frm.doc }).then((rows) => {
			if (!rows || !rows.length) {
				return;
			}

			const applyAction = (action) => {
				frappe.dom.freeze();
				frappe
					.xcall("frappe.model.workflow.apply_workflow", {
						doc: frm.doc,
						action,
					})
					.then((doc) => {
						frappe.model.sync(doc);
						frm.refresh();
					})
					.finally(() => frappe.dom.unfreeze());
			};

			const [primary, ...secondary] = rows;
			frm.page.set_primary_action(__(primary.action), () => applyAction(primary.action));
			secondary.forEach((row) => {
				frm.add_custom_button(__(row.action), () => applyAction(row.action));
			});
		});
	},
});
